// 系统 AI 配置后台接口封装。
//
// 路径与后端 controller 的方法名按 AutoRegisterRoute 的驼峰转路径规则一一对应：
// GetAiSystemConfig → /ai/system/config，PostAiSystemConfigSet → /ai/system/config/set。
import httpRequest from "@/apis/axios-api";

import type { CodeResult } from "@/types/request";
import type { AiSystemConfigView, SaveAiSystemConfigRequest } from "@/types/ai-system-config";

// 读取系统级 AI 配置（密钥只返回掩码，不返回明文）
export function GetAiSystemConfig(): Promise<CodeResult<AiSystemConfigView>> {
  return httpRequest<unknown, CodeResult<AiSystemConfigView>>({
    url: "/ai/system/config",
    method: "get",
  });
}

// 保存系统级 AI 配置，返回保存后的最新视图（api_key 留空表示不修改已保存的密钥）
export function PostAiSystemConfigSet(
  req: SaveAiSystemConfigRequest
): Promise<CodeResult<AiSystemConfigView>> {
  return httpRequest<unknown, CodeResult<AiSystemConfigView>>({
    url: "/ai/system/config/set",
    method: "post",
    data: req,
  });
}
